double sign = (n % 2 == 0) ? 1.0 : -1.0;
double pi = std::acos(-1.0);
double prefactor = sign / pi;

double sqrt_factor = std::sqrt(std::tgamma(static_cast<double>(n) + 1.0) /
                               std::tgamma(static_cast<double>(n + k) + 1.0));

double exp_factor = std::exp(-2.0 * r * r);
double r_pow = std::pow(2.0 * r, static_cast<double>(k));

double x = 4.0 * r * r;
double laguerre = 0.0;
for (std::size_t m = 0; m <= n; ++m) {
    double term_sign = (m % 2 == 0) ? 1.0 : -1.0;
    double binom = std::tgamma(static_cast<double>(n + k) + 1.0) /
                   (std::tgamma(static_cast<double>(n - m) + 1.0) *
                    std::tgamma(static_cast<double>(k + m) + 1.0));
    double term = term_sign * binom *
                  std::pow(x, static_cast<double>(m)) /
                  std::tgamma(static_cast<double>(m) + 1.0);
    laguerre += term;
}

return prefactor * sqrt_factor * exp_factor * r_pow * laguerre;

